content.text:
{
  "examples": [
    {
      "description": "2-layer USB-C environmental sensor logger: STM32F103 MCU, BME680 sensor, AMS1117 LDO regulator, I2C bus with pull-ups, hardware reset circuit, UART debug header.",
      "file": "examples/env_logger/env_logger.synth",
      "source": "  // 2-Layer USB-C Environmental Sensor Logger Board
  //   USB-C Input (5V) -> AMS1117 3V3 Regulator -> STM32F103 MCU & BME680 Sensor
  //   Features:
  //     - USB-C connector (VBUS 5V input) with 5.1k CC1/CC2 pull-down resistors for USB-C PD 5V negotiation
  //     - AMS1117-3.3 LDO regulator with input, output bulk, and MLCC decoupling capacitors
  //     - STM32F103C8 ARM Cortex-M3 microcontroller with dedicated VDD/VBAT decoupling and 10k BOOT0 pull-down
  //     - 4-pin UART/Debug header (3V3, TX, RX, GND)
  //     - Bosch BME680 Environmental Sensor (Temp, Humidity, Pressure, Gas/VOC) with CSB tied high (I2C mode) and SDO tied low (addr 0x76)
  //     - I2C bus (PB6 SCL, PB7 SDA) with dual 4.7k pull-up resistors
  //     - Hardware Reset circuit (push button, 10k pull-up resistor, 100nF filter capacitor)

board "env_logger" {
    layers 2
    manufacturer "jlcpcb"

    // ---- Power Chain (USB-C 5V to 3.3V LDO) --------------------------------
    group "USB-C INPUT / 3V3 LDO" color "#c2410c" {
      component J1: connector  "usb_c_receptacle"
      component R_CC1: resistor "r_generic_0603" value "5.1k"   // 5.1k CC1 pull-down to GND
      component R_CC2: resistor "r_generic_0603" value "5.1k"   // 5.1k CC2 pull-down to GND
      component U1: regulator  "ams1117_3v3" value "AMS1117-3.3"
      component C1: capacitor  "c_generic_0805" value "10uF"   // VBUS 5V bulk capacitor
      component C2: capacitor  "c_generic_0805" value "22uF"   // AMS1117 input capacitor (22uF)
      component C3: capacitor  "c_generic_0805" value "22uF"   // AMS1117 output capacitor (22uF)
      component C7: capacitor  "c_generic_0603" value "100nF"   // AMS1117 output 100nF decoupling
      notes "" {
        "VBUS 5 V in; AMS1117-3.3 LDO, always on."
        "CC1/CC2 pulled down 5.1k each: advertises a 5 V sink."
      }
    }

    connect J1.vbus -> C1.p1
    connect J1.gnd  -> C1.p2

    // USB-C CC pin 5.1k pull-down resistors for 5V VBUS power negotiation
    connect J1.cc1   -> R_CC1.p1
    connect J1.gnd   -> R_CC1.p2
    connect J1.cc2   -> R_CC2.p1
    connect J1.gnd   -> R_CC2.p2

    connect J1.vbus -> U1.vin
    connect J1.gnd  -> U1.gnd

    connect U1.vin  -> C2.p1
    connect U1.gnd  -> C2.p2

    connect U1.vout -> C3.p1
    connect U1.gnd  -> C3.p2

    connect U1.vout -> C7.p1
    connect U1.gnd  -> C7.p2

    // ---- MCU + Reset & Debug Circuit ----------------------------------------
    group "STM32F103 MCU" color "#0072b2" {
      component U2: mcu        "stm32f103c8"
      component J2: connector  "header_1x4"       // 4-pin Debug Header (3V3, TX, RX, GND)
      component C4: capacitor  "c_generic_0603" value "100nF" { placement_hint { near: "U2" priority: hard } }   // STM32 VDD decoupling capacitor (100nF)
      component C8: capacitor  "c_generic_0603" value "100nF" { placement_hint { near: "U2" priority: hard } }   // STM32 VBAT decoupling capacitor (100nF)
      component R1: resistor   "r_generic_0603" value "10k" { placement_hint { near: "U2" priority: hard } }   // NRST pull-up resistor (10k)
      component R_BOOT0: resistor "r_generic_0603" value "10k" { placement_hint { near: "U2" priority: hard } } // BOOT0 pull-down resistor (10k)
      component SW1: switch    "spst_tactile"     // Tactile reset button
      component C5: capacitor  "c_generic_0603" value "100nF" { placement_hint { near: "U2" priority: hard } }   // Reset pin filter capacitor (100nF)
      notes "" {
        "BOOT0 pulled low: boots from flash."
        "Debug header J2: 3V3 / TX / RX / GND, in pin order."
      }
    }

    connect U1.vout -> U2.vdd
    connect U1.vout -> U2.vdd_2
    connect U1.vout -> U2.vdd_3
    connect U1.vout -> U2.vbat
    connect U1.vout -> U2.vdda
    connect U1.gnd  -> U2.vss
    connect U1.gnd  -> U2.vss_2
    connect U1.gnd  -> U2.vss_3
    connect U1.gnd  -> U2.vssa

    connect U2.vdd  -> C4.p1
    connect U2.vss  -> C4.p2

    connect U2.vbat -> C8.p1
    connect U2.vss  -> C8.p2

    connect U1.vout -> R1.p1
    connect R1.p2   -> U2.nrst

    connect U2.boot0   -> R_BOOT0.p1
    connect J1.gnd     -> R_BOOT0.p2

    connect U2.nrst -> SW1.p1
    connect SW1.p2  -> U2.vss

    connect U2.nrst -> C5.p1
    connect U2.vss  -> C5.p2

    // Debug Header connections (Pin 1: 3V3, Pin 2: PA9 TX, Pin 3: PA10 RX, Pin 4: GND)
    connect U1.vout -> J2.p1
    connect U2.pa9  -> J2.p2
    connect U2.pa10 -> J2.p3
    connect U1.gnd  -> J2.p4

    // ---- BME680 Environmental Sensor & I2C Bus -----------------------------
    group "BME680 SENSOR" color "#0a7d4a" {
      component U3: sensor     "bme680_env"
      component C6: capacitor  "c_generic_0603" value "100nF"   // BME680 VDD decoupling capacitor (100nF)
      component R2: resistor   "r_generic_0603" value "4.7k"   // I2C SDA pull-up resistor (4.7k)
      component R3: resistor   "r_generic_0603" value "4.7k"   // I2C SCL pull-up resistor (4.7k)
      notes "" {
        "I2C address 0x76 (SDO tied low); CSB high selects I2C."
        "4.7k bus pull-ups sized for 400 kHz at 3.3 V."
      }
    }

    connect U1.vout -> U3.vdd
    connect U1.gnd  -> U3.gnd

    // BME680 I2C protocol mode selection (CSB -> 3V3) & fixed I2C address 0x76 (SDO -> GND)
    connect U3.csb  -> U1.vout
    connect U3.sdo  -> U1.gnd

    connect U3.vdd  -> C6.p1
    connect U3.gnd  -> C6.p2

    connect U2.pb7  -> U3.sda
    connect U2.pb6  -> U3.scl

    connect U2.pb7  -> R2.p1
    connect R2.p2   -> U1.vout

    connect U2.pb6  -> R3.p1
    connect R3.p2   -> U1.vout
  }
"
    },
    {
      "description": "4-layer sensor logger: ATmega328P MCU, USB-C with ESD protection diodes, two I2C environmental sensors, SPI NOR flash, status LEDs.",
      "file": "examples/sensor_logger/sensor_logger.synth",
      "source": "// Sensor-logger dev board:
//   USB-C in -> AMS1117 3V3 regulator -> ATmega328P MCU.
//   I2C bus with two environmental sensors + pullups.
//   SPI flash for log storage.
//   Reset button, status LEDs (red/green/blue), decoupling.
//
// Exercises ~12 different part types and ~30 nets, which is enough
// to stress the schematic layout/labeling logic without being a
// production-grade design.
board "sensor_logger" {
  layers 4
  manufacturer "jlcpcb"

  // ---- Power chain --------------------------------------------------------
  component J1: connector  "usb_c_receptacle"
  component D1: diode      "esd_usb"
  component D2: diode      "esd_usb"
  component U1: regulator  "ams1117_3v3"
  component C1: capacitor  "c_generic_0805" value "10uF"   // bulk on VBUS (5V)
  component C2: capacitor  "c_generic_0805" value "22uF"   // input cap on regulator
  component C3: capacitor  "c_generic_0805" value "22uF"   // output cap on regulator
  component C4: capacitor  "c_generic_0603" value "100nF"   // 3V3 decoupling

  connect J1.vbus -> C1.p1
  connect J1.gnd  -> C1.p2
  connect J1.vbus -> U1.vin
  connect J1.gnd  -> U1.gnd
  connect U1.vin  -> C2.p1
  connect U1.gnd  -> C2.p2
  connect U1.vout -> C3.p1
  connect U1.gnd  -> C3.p2
  connect U1.vout -> C4.p1
  connect U1.gnd  -> C4.p2

  // ESD protection on USB DP/DN.
  // USB-C sink: 5.1k Rd on each CC pin, or a compliant source never turns
  // VBUS on.
  component R9:  resistor  "r_generic_0603" value "5.1k" { placement_hint { near: "J1" priority: hard } }
  component R10: resistor  "r_generic_0603" value "5.1k" { placement_hint { near: "J1" priority: hard } }
  connect J1.cc1 -> R9.p1
  connect J1.gnd -> R9.p2
  connect J1.cc2 -> R10.p1
  connect J1.gnd -> R10.p2

  connect J1.dp  -> D1.io
  connect J1.gnd -> D1.gnd
  connect J1.dn  -> D2.io
  connect J1.gnd -> D2.gnd

  // ---- MCU + reset --------------------------------------------------------
  component U2: mcu        "atmega328p"
  component C5: capacitor  "c_generic_0603" value "100nF" { placement_hint { near: "U2" priority: hard } } // MCU decoupling
  component R1: resistor   "r_generic_0603" value "10k"  // reset pullup
  component SW1: switch    "spst_tactile"
  component C6: capacitor  "c_generic_0603" value "100nF"  // reset cap

  connect U1.vout -> U2.vcc
  connect U1.vout -> U2.avcc
  connect U1.gnd  -> U2.gnd
  connect U1.gnd  -> U2.gnd_2
  connect U2.vcc  -> C5.p1
  connect U2.gnd  -> C5.p2
  connect U2.vcc  -> R1.p1
  connect R1.p2   -> U2.reset
  connect U2.reset -> SW1.p1
  connect SW1.p2  -> U2.gnd
  connect U2.reset -> C6.p1
  connect U2.gnd  -> C6.p2

  // ---- I2C bus + sensors + pullups ----------------------------------------
  component U3: sensor     "bmp280_pressure"
  component U4: sensor     "bme680_env"
  component C7: capacitor  "c_generic_0603" value "100nF" { placement_hint { near: "U3" priority: hard } }
  component C8: capacitor  "c_generic_0603" value "100nF" { placement_hint { near: "U4" priority: hard } }
  component R2: resistor   "r_generic_0603" value "4.7k"  // SDA pullup
  component R3: resistor   "r_generic_0603" value "4.7k"  // SCL pullup

  connect U1.vout -> U3.vdd
  connect U1.gnd  -> U3.gnd
  connect U1.vout -> U4.vdd
  connect U1.gnd  -> U4.gnd
  connect U3.vdd  -> C7.p1
  connect U3.gnd  -> C7.p2
  connect U4.vdd  -> C8.p1
  connect U4.gnd  -> C8.p2

  connect U2.pc4_sda -> U3.sda
  connect U2.pc4_sda -> U4.sda
  connect U2.pc5_scl -> U3.scl
  connect U2.pc5_scl -> U4.scl
  // BME680 interface mode select: CSB=VDD selects I2C; SDO=GND selects addr 0x76
  connect U4.vdd -> U4.csb
  connect U4.gnd -> U4.sdo
  connect U2.pc4_sda -> R2.p1
  connect R2.p2      -> U2.vcc
  connect U2.pc5_scl -> R3.p1
  connect R3.p2      -> U2.vcc

  // ---- SPI flash ----------------------------------------------------------
  component U5: memory     "w25q128_flash"
  component C9: capacitor  "c_generic_0603" value "100nF" { placement_hint { near: "U5" priority: hard } }
  component R7: resistor   "r_generic_0603" value "10k"   // /WP pull-up
  component R8: resistor   "r_generic_0603" value "10k"   // /HOLD pull-up

  connect U1.vout    -> U5.vcc
  connect U1.gnd     -> U5.gnd
  connect U5.vcc     -> C9.p1
  connect U5.gnd     -> C9.p2
  connect U2.pb3_mosi -> U5.io0   // IO0 = DI in single-SPI mode
  connect U2.pb4_miso -> U5.io1   // IO1 = DO in single-SPI mode
  connect U2.pb5_sck  -> U5.clk
  connect U2.pb2_ss   -> U5.cs
  // /WP and /HOLD pulled high through 10k rather than strapped to the
  // rail: both are bidirectional IO lines in quad mode, so a hard tie
  // to VOUT is a driver conflict if the part is ever run quad.
  connect U5.io2      -> R7.p1
  connect R7.p2       -> U5.vcc
  connect U5.io3      -> R8.p1
  connect R8.p2       -> U5.vcc

  // ---- Status LEDs (red / green / blue) ----------------------------------
  component R4: resistor  "r_generic_0603" value "1k" { placement_hint { near: "U2" side: left } }
  component D3: diode     "led_red_0603" { placement_hint { near: "R4" } }
  component R5: resistor  "r_generic_0603" value "1k" { placement_hint { near: "U2" side: left } }
  component D4: diode     "led_green_0603" { placement_hint { near: "R5" } }
  component R6: resistor  "r_generic_0603" value "1k" { placement_hint { near: "U2" side: left } }
  component D5: diode     "led_blue_0603" { placement_hint { near: "R6" } }

  connect U2.pd0_rx -> R4.p1
  connect R4.p2     -> D3.anode
  connect D3.cathode -> U2.gnd

  connect U2.pd1_tx -> R5.p1
  connect R5.p2     -> D4.anode
  connect D4.cathode -> U2.gnd

  connect U2.reset  -> R6.p1
  connect R6.p2     -> D5.anode
  connect D5.cathode -> U2.gnd

  // ---- USB differential pair (removed: ATmega328P has no native USB;
  // J1.dp / J1.dn nets are auto-named and cannot be referenced by a diff_pair
  // block. Re-add when a design uses a USB-capable MCU and labels these nets.) --
}
"
    },
    {
      "description": "Compact board isolating features the other two examples don't exercise: a hard placement_hint pinning the MCU to a board region, a diff_pair with a target impedance resolved via the <REFDES>_<pin> endpoint convention, and a keepout zone.",
      "file": "examples/placement_and_diff_pair/placement_and_diff_pair.synth",
      "source": "// Compact demo of features the other two example boards don't use:
// a hard placement_hint, a differential pair with impedance, and a
// keepout zone.
board "placement_and_diff_pair" {
  layers 4
  manufacturer "jlcpcb"

  // Pin the MCU into the top-left corner and keep it there even if
  // the placer would otherwise prefer a different spot.
  component U1: mcu "rp2350" {
    placement_hint { region: top_left priority: hard }
  }
  component J1: connector "usb_c_receptacle"
  component C1: capacitor "c_generic_0805" value "10uF"

  connect J1.vbus -> C1.p1
  connect J1.gnd  -> C1.p2
  connect J1.gnd  -> U1.gnd
  connect J1.vbus -> U1.iovdd
  connect J1.vbus -> U1.dvdd
  connect J1.vbus -> U1.dvdd3
  connect J1.vbus -> U1.run

  // USB D+/D- run from the connector straight to the MCU's native
  // USB pins, so the pair's endpoint on U1 fully identifies the net.
  // USB-C sink: 5.1k Rd on each CC pin, or a compliant source never turns
  // VBUS on.
  component R1: resistor "r_generic_0603" value "5.1k"
  component R2: resistor "r_generic_0603" value "5.1k"
  connect J1.cc1 -> R1.p1
  connect J1.gnd -> R1.p2
  connect J1.cc2 -> R2.p1
  connect J1.gnd -> R2.p2

  connect J1.dp -> U1.usb_dp
  connect J1.dn -> U1.usb_dn

  // diff_pair has no separate net-naming syntax in V1: each leg is
  // written as <REFDES>_<pin>, matched against any net that has that
  // component/pin as one of its endpoints.
  diff_pair U1_usb_dp U1_usb_dn {
    impedance 90ohm
  }

  keepout usb_connector_zone {
    radius 8mm
  }
}
"
    }
  ],
  "grammar": {
    "comments": "// line comment to end of line. No block comments.",
    "component_kinds_seen_in_registry": [
      "antenna",
      "buzzer",
      "capacitor",
      "charger",
      "connector",
      "crystal",
      "diode",
      "display",
      "filter",
      "fuse",
      "ic",
      "inductor",
      "led",
      "level_shifter",
      "mcu",
      "memory",
      "modem",
      "opamp",
      "regulator",
      "resistor",
      "secure_element",
      "sensor",
      "switch",
      "transistor"
    ],
    "placement_hint_attrs": {
      "edge": [
        "top",
        "bottom",
        "left",
        "right"
      ],
      "near": "another component's REFDES",
      "priority": [
        "hard",
        "soft"
      ],
      "region": [
        "top_left",
        "top_right",
        "bottom_left",
        "bottom_right",
        "centre",
        "top_edge",
        "bottom_edge",
        "left_edge",
        "right_edge"
      ],
      "side": [
        "above",
        "below",
        "left",
        "right"
      ]
    },
    "statements": [
      {
        "description": "Inlines another .synth file's statements at this point. Path must be relative with no `..` segments, resolved from the importing file's directory. Import cycles are rejected.",
        "form": "import "<relative/path.synth>"",
        "where": "zero or more, before the `board { ... }` block"
      },
      {
        "description": "Copper layer count (commonly 2 or 4). At most one per board.",
        "example": "layers 4",
        "form": "layers <integer>"
      },
      {
        "description": "Selects the DRC/manufacturing profile. At most one per board.",
        "example": "manufacturer "jlcpcb"",
        "form": "manufacturer "<name>""
      },
      {
        "description": "Declares a fabrication process the board cannot be built without. `via_in_pad` is the only one today: the process must fill and cap a via drilled inside an SMD pad, which at fine pitch is the only escape the geometry leaves. A requirement is not a permission — it is matched against the `manufacturer` profile's capability, and a tier that does not offer the process is an error rather than a silent downgrade. `jlcpcb`, `pcbway` and `oshpark` do not offer `via_in_pad`; `manufacturer "jlc-filled-via"` (JLCPCB with the resin-filled via option) does. Repeat the statement for several processes; declaring one twice is one requirement.",
        "example": "requires via_in_pad",
        "form": "requires <process>"
      },
      {
        "description": "Board revision tag (e.g. "A", "1.2") carried into the schematic title block's Revision field. At most one per board; optional.",
        "example": "revision "A"",
        "form": "revision "<tag>""
      },
      {
        "description": "Declares a component. <REFDES> is a unique designator (U1, C3, R12, ...). <kind> is a coarse category — see component_kinds_seen_in_registry below. <part_id> is a registry part id; call synth_search_registry to find valid (kind, part_id) pairs and the part's real pin names before writing `connect` lines. `value "..."` is an optional display value (e.g. "10k") for the schematic Value field and BOM.",
        "example": "component R1: resistor "r_generic_0603" value "10k"",
        "form": "component <REFDES>: <kind> "<part_id>" [value "<display>"]"
      },
      {
        "description": "How this package's pins leave it. A dense grid array — three pad rows and three columns, at or below 1.3 mm pitch — is escaped before routing whether or not it says so, because a fine-pitch array left to a general router comes back with a stub on every lane. This block overrides that: `method` picks the engine (`underpad` drops a via inside each pad, the only method a fully populated array leaves open; `channel` routes out between the pads), `layers` limits which copper the escape may use, and `off` leaves the package to the general router. `off` wins over a method on the same package. The escape via is sized from the declared manufacturer's floor, not from this block.",
        "example": "component U1: fpga "ice40hx4k_bg121" { escape { method underpad layers "In1.Cu", "In2.Cu" } }",
        "form": "component <REFDES>: <kind> "<part_id>" { escape { [method <channel|underpad>] [layers "<layer>", …] [off] } }"
      },
      {
        "description": "Same as the plain component form, plus a placement_hint block. All attrs inside placement_hint are optional and independent; include only the ones you need.",
        "example": "component U1: mcu "stm32h743" { placement_hint { region: top_left priority: hard } }",
        "form": "component <REFDES>: <kind> "<part_id>" { placement_hint { region: <region> edge: <edge> near: <REFDES> side: <side> priority: <hard|soft> } }"
      },
      {
        "description": "Wires two component pins onto the same net. Pin names come from the part's registry entry. Repeat `connect` lines that share an endpoint to fan a net out to more than two pins.",
        "example": "connect U1.vout -> C3.p1",
        "form": "connect <REFDES>.<pin> -> <REFDES>.<pin>"
      },
      {
        "description": "Marks two already-connected nets as a differential pair for routing, with a target characteristic impedance.",
        "example": "diff_pair USB_DP USB_DN { impedance 90ohm }",
        "form": "diff_pair <NET_P> <NET_N> { impedance <value><unit> }"
      },
      {
        "description": "Declares a circular routing keepout zone (e.g. under an antenna).",
        "example": "keepout antenna { radius 15mm }",
        "form": "keepout <name> { radius <value><unit> }"
      },
      {
        "description": "Declares the board's physical layers from the top of the board to the bottom: copper and insulator entries that alternate, starting and ending with copper. The number of copper entries must equal `layers`, and `layers` must be 2, 4 or 6 (E-SYNTH-STACKUP-001). Thicknesses are lengths (mm or mil); `er` is the insulator's dielectric constant, a plain number. The exporter writes it to the .kicad_pcb stackup section and sets the board thickness to the stack total. Synth has no fabricator presets and no default stack: omit the block and the board exports the exporter's default thickness with no stackup section.",
        "example": "stackup { copper 0.035mm insulator 1.5mm er 4.4 material "FR4" copper 0.035mm }",
        "form": "stackup { copper <thickness><unit> | insulator <thickness><unit> er <number> [material "<name>"] ... }"
      },
      {
        "description": "Declares a sub-circuit region. THE most important statement for schematic readability: a group becomes a titled, coloured, dashed box on the sheet, its members are placed together inside it, and nets that stay inside it are drawn as wires while nets crossing out of it become labels. Components keep board-unique refdes and may be connected across groups. Prefer 3-6 groups naming the functional blocks (power input, MCU, sensor, ...). `color` overrides the deterministic palette hue; `title` sets a display title different from the identifier; `region` steers which page quadrant it packs toward.",
        "example": "group "3V3 LDO" color "#c2410c" { component U2: regulator "ap2112k_3v3" value "AP2112K-3.3" }",
        "form": "group "<title>" [color "#rrggbb"] [title "<display>"] [region <region>] { <statement>* }"
      },
      {
        "description": "Free prose rendered on the sheet. Inside a `group` the block is drawn at the bottom of that group's box; at board level it stacks below all content. Use it for the intent the netlist cannot carry: I2C addresses, strap choices, current budgets, assembly notes. Pass an empty title ("") for an untitled block.",
        "example": "notes "" { "I2C address 0x76 (SDO tied low)." "4.7k pull-ups sized for 400 kHz at 3.3 V." }",
        "form": "notes "<title>" { "<line>"* }"
      },
      {
        "description": "Declares a named power rail with a nominal voltage. Rails become power symbols on the schematic instead of drawn wires, and the declared voltage feeds the voltage-domain ERC rules rather than being guessed from pin names. A bare declaration still materialises the net so later `connect ... as "<RAIL>"` lines join it.",
        "example": "power "+3V3" 3.3v",
        "form": "power "<RAIL>" <value><unit> [class "<netclass>"] [{ <REFDES>.<pin>* }]"
      },
      {
        "description": "Names a net explicitly. A named net renders its name as the schematic label; an unnamed net is auto-named (net_7) and `E-SYNTH-SCHEM-014` flags it if it reaches the sheet. Names should be UPPERCASE and <= 16 characters (`E-SYNTH-SCHEM-008/009`).",
        "example": "net "I2C_SCL" { U1.scl U2.pb6 }",
        "form": "net "<NAME>" [class "<netclass>"] [{ <REFDES>.<pin>* }]"
      },
      {
        "description": "Routing and colour class. Nets are auto-classified (Power, Ground, I2C, SPI, UART, USB, Clock, Reset) and coloured from a fixed palette; a declared class joined with `class "<name>"` overrides both. `color` sets the schematic wire/label hue and the PCB net colour. `layers` pins the class's nets to KiCad copper layers (`"F.Cu"`, `"In1.Cu"`, `"B.Cu"`): the router keeps them there, the export writes it as a KiCad custom rule, and copper elsewhere is E-SYNTH-DRC-023. Pin a controlled-impedance pair to outer layers to clear W-SYNTH-IMPEDANCE-001.",
        "example": "netclass "PWR" { trace_width 0.4mm clearance 0.25mm color "#d55e00" }",
        "form": "netclass "<name>" { [trace_width <value><unit>] [clearance <value><unit>] [via_diameter <value><unit>] [via_drill <value><unit>] [layers "<layer>", …] [color "#rrggbb"] }"
      },
      {
        "description": "Same as plain `connect`, but joins the named net instead of an auto-named one. This is the usual way to put a connection on a declared `power` rail or a semantic signal name.",
        "example": "connect U1.vout -> U2.vdd as "+3V3"",
        "form": "connect <REFDES>.<pin> -> <REFDES>.<pin> as "<NET_NAME>""
      },
      {
        "description": "Connector pin legends, default off. When on, each external connector gets a compact pin:net list beside it. Off is usually right: a one-line `notes` block reads better than a generated table, and no-connect crosses already mark unused pins.",
        "example": "legends on",
        "form": "legends <on|off>"
      },
      {
        "description": "Design-authority name for the schematic title block's Company field. Distinct from `manufacturer`, which names who builds the board.",
        "example": "company "Acme Robotics"",
        "form": "company "<name>""
      },
      {
        "description": "A hierarchical-sheet boundary. Statements lower exactly as in a `group` (refdes stay board-unique, cross-sheet `connect` is allowed), but the name is also a split point: a board whose single-sheet content overflows A2 and which has two or more populated boundaries exports as a KiCad hierarchy, one file per sheet. Small boards stay on one page.",
        "example": "sheet "Power" { component U1: regulator "ams1117_3v3" }",
        "form": "sheet "<name>" { <statement>* }"
      },
      {
        "description": "A build variant sharing one schematic and layout but leaving the listed refdes unpopulated. Exports as KiCad 10 native variants plus one bom.<variant>.csv per variant. ERC still checks DNP parts.",
        "example": "variant "lite" description "No radio" { dnp U3 U4 }",
        "form": "variant "<name>" [description "<text>"] { dnp <REFDES>* }"
      },
      {
        "description": "A reusable parameterised sub-circuit definition. Instantiate with `use`. Ports are typed by a declared `interface`; bind them at the instantiation site with `bind`.",
        "example": "module LedBank(count = 3) { port ctrl: Gpio component R1: resistor "r_generic_0603" value "1k" }",
        "form": "module <Name> [( <param> = <default>, ... )] { port <Port>: <interface> ... <statement>* }"
      },
      {
        "description": "Module plumbing. `interface` names a signal bundle a port can carry, `bus` groups member nets under one name, `use` instantiates a module under a refdes prefix, and `bind` wires an instance port to a net or interface.",
        "example": "use LedBank as LB1 ( count = 4 )",
        "form": "interface <Name> { <signal>* }   |   bus <Name> { <member>* }   |   use <Module> as <Prefix> [( <param> = <value> )]   |   bind <Prefix>.<Port> -> <target>"
      }
    ],
    "top_level": "[import "relative/path.synth"]*  board "<name>" { <statement>* }",
    "units": [
      "mm",
      "mil",
      "ohm",
      "kohm",
      "mohm",
      "v",
      "mv",
      "a",
      "ma",
      "mhz",
      "ghz",
      "pf",
      "nf",
      "uf"
    ]
  },
  "language": "SynthSpec (.synth)",
  "note": "This is the .synth design-input language grammar. It is distinct from the diagnostic JSON wire format documented in docs/protocol-v1.0.md (that covers synth_validate's output shape, not this input syntax).",
  "workflow_tip": "1) synth_search_registry to find real (kind, part_id) pairs and exact pin names. 2) Draft the .synth source using the grammar above. Put every component inside a `group` and give each group a `notes` block - grouping is what makes the generated sheet readable, and an ungrouped board lays out as one flat band. Give every generic passive a `value` (a missing one is an error, E-SYNTH-VALUE-001). 3) synth_validate it: this returns electrical ERC *and* the readability rules (E-SYNTH-SCHEM-*). 4) synth_fix in a loop over diagnostics with suggested_fixes until clean. 5) synth_preview_schematic to inspect group_boxes/annotations before exporting. 6) synth_export."
}

