  net "SD_DQ9"  class "SDDATA" { U3.iol_2b U4.dq9 }
  net "SD_DQ10" class "SDDATA" { U3.iol_5a U4.dq10 }
  net "SD_DQ11" class "SDDATA" { U3.iol_9a U4.dq11 }
  net "SD_DQ12" class "SDDATA" { U3.iol_10a U4.dq12 }
  net "SD_DQ13" class "SDDATA" { U3.iol_12b U4.dq13 }
  net "SD_DQ14" class "SDDATA" { U3.iol_14b U4.dq14 }
