  net "SD_A2"  class "SDADDR" { U3.iot_223 U4.a2 }
  net "SD_A3"  class "SDADDR" { U3.iot_211 U4.a3 }
  net "SD_A4"  class "SDADDR" { U3.iot_207 U4.a4 }
  net "SD_A5"  class "SDADDR" { U3.iot_206 U4.a5 }
