  net "SD_A8"  class "SDADDR" { U3.iot_178 U4.a8 }
  net "SD_A9"  class "SDADDR" { U3.iot_170 U4.a9 }
  net "SD_A10" class "SDADDR" { U3.iot_168 U4.a10 }
  net "SD_A11" class "SDADDR" { U3.iot_174 U4.a11 }
  net "SD_BA0" class "SDADDR" { U3.iol_25b U4.ba0 }
  net "SD_BA1" class "SDADDR" { U3.iol_25a U4.ba1 }
  net "SD_LDQM" class "SDADDR" { U3.iob_61 U4.ldqm }
  net "SD_UDQM" class "SDADDR" { U3.iob_71 U4.udqm }

  // ---- SDRAM command group and clock (22 ohm at the FPGA end) -------------------------
  net "SD_CS_F"  class "SDADDR" { U3.iot_219 RS2.p1 }
